use byteorder::{BigEndian, ByteOrder};
use proc_macro2::TokenStream;

pub fn decode_and_count(bytes: &[u8; 4], source: &str) -> Result<(u32, usize), proc_macro2::LexError> {
    let value = BigEndian::read_u32(bytes);
    let stream: TokenStream = source.parse()?;
    Ok((value, stream.into_iter().count()))
}

pub fn identifier_start(character: char) -> bool {
    unicode_ident::is_xid_start(character)
}

pub fn formatted_once(value: f64) -> (String, u32) {
    static NUMBER: once_cell::sync::Lazy<u32> = once_cell::sync::Lazy::new(|| 42);
    let mut buffer = ryu::Buffer::new();
    (buffer.format(value).to_owned(), *NUMBER)
}

