use b06_probe::{decode_and_count, formatted_once, identifier_start};

#[test]
fn cross_crate_probe() {
    assert_eq!(decode_and_count(&[0, 0, 0, 7], "token").unwrap(), (7, 1));
    assert!(identifier_start('a'));
    assert_eq!(formatted_once(1.5), ("1.5".to_owned(), 42));
}
